// src/js/Chat/Emoji/EmojiFallback.js
import twemoji from "twemoji";

/**
 * Detecta se o navegador consegue renderizar um emoji corretamente.
 */
export function emojiNeedsFallback(emoji) {
  const span = document.createElement("span");
  span.textContent = emoji;

  // Navegador falhou se output não igual a entrada
  return span.innerText !== emoji;
}

/**
 * Converte somente os emojis que falharem para Twemoji.
 */
export function applyEmojiFallback(html) {
  const div = document.createElement("div");
  div.innerHTML = html;

  const nodes = div.querySelectorAll("*");

  nodes.forEach(node => {
    if (node.childNodes.length === 1 && node.childNodes[0].nodeType === 3) {
      const text = node.textContent;

      // Verificar caractere por caractere
      let result = "";
      for (const char of [...text]) {
        if (emojiNeedsFallback(char)) {
          result += twemoji.parse(char, {
            folder: "svg",
            ext: ".svg",
            className: "twemoji"
          });
        } else {
          result += char;
        }
      }

      node.innerHTML = result;
    }
  });

  return div.innerHTML;
}
